def struct_color(g, markers):
    best, bestc = -1, None
    for c in set(x for r in g for x in r) - markers:
        f = 0
        for r in g:
            nm = [x for x in r if x not in markers]
            if nm:
                f = max(f, sum(1 for x in nm if x == c) / len(nm))
        if f > best:
            best, bestc = f, c
    return bestc

def transform(g):
    H, W = len(g), len(g[0])
    cnt = collections.Counter(x for r in g for x in r)
    markers = {c for c, n in cnt.items() if n < 0.15 * H * W}
    st = struct_color(g, markers)
    mrows = sorted({i for i in range(H) for j in range(W) if g[i][j] in markers})
    mcols = sorted({j for i in range(H) for j in range(W) if g[i][j] in markers})
    out = []
    for a in range(len(mrows) - 1):
        row = []
        for b in range(len(mcols) - 1):
            cs = {g[mrows[a]][mcols[b]], g[mrows[a]][mcols[b+1]],
                  g[mrows[a+1]][mcols[b]], g[mrows[a+1]][mcols[b+1]]}
            row.append(cs.pop() if len(cs) == 1 else st)
        out.append(row)
    return out

